 R=len(src);C=len(src[0]);dirs=[(dr,dc,diag if dr and dc else orth) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]
 sdirs=[(dr,dc) for dr,dc,w in dirs if seedconn==8 or abs(dr)+abs(dc)==1]
 seen=set(); comps=[]
 for r in range(R):
  for c in range(C):
   if src[r][c] not in (target,bg) and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));cc=[]
    while q:
     x,y=q.pop();cc.append((x,y))
     for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
      a,b=x+dr,y+dc
      if 0<=a<R and 0<=b<C and src[a][b] not in (target,bg) and (a,b) not in seen:seen.add((a,b));q.append((a,b))
    color=Counter(src[x][y] for x,y in cc).most_common(1)[0][0];comps.append((color,cc))
 vals=set(x for row in src for x in row if x not in (target,bg));ds={v:[[float('inf')]*C for _ in range(R)] for v in vals}
 for v in vals:
  hp=[]
  for color,cc in comps:
   if color==v:
    for x,y in cc:
     for dr,dc in sdirs:
      a,b=x+dr,y+dc
      if 0<=a<R and 0<=b<C and src[a][b]==target and ds[v][a][b]>0:ds[v][a][b]=0;heapq.heappush(hp,(0.,a,b))
  while hp:
   d,x,y=heapq.heappop(hp)
   for dr,dc,w in dirs:
    a,b=x+dr,y+dc
    if 0<=a<R and 0<=b<C and src[a][b]==target and d+w<ds[v][a][b]:ds[v][a][b]=d+w;heapq.heappush(hp,(d+w,a,b))
 out=[row[:] for row in src]
 for r in range(R):
  for c in range(C):
   if src[r][c]==target:
    l=sorted((ds[v][r][c],v) for v in vals)
