def transform_centroid(src,target,bg):
 R=len(src);C=len(src[0]);dirs=((1,0),(-1,0),(0,1),(0,-1));seen=set();comps=[]
 for r in range(R):
  for c in range(C):
   if src[r][c] not in (target,bg) and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));cc=[]
    while q:
     x,y=q.pop();cc.append((x,y))
     for dr,dc in dirs:
      a,b=x+dr,y+dc
      if 0<=a<R and 0<=b<C and src[a][b] not in (target,bg) and (a,b) not in seen:seen.add((a,b));q.append((a,b))
    v=Counter(src[x][y] for x,y in cc).most_common(1)[0][0];comps.append((v,cc))
 vals=set(v for row in src for v in row if v not in (target,bg));ds={v:[[999]*C for _ in range(R)] for v in vals}
 for v in vals:
  q=deque()
  for col,cc in comps:
   if col!=v:continue
   center=(sum(x for x,y in cc)/len(cc),sum(y for x,y in cc)/len(cc))
   adj=set((x+dr,y+dc) for x,y in cc for dr,dc in dirs if 0<=x+dr<R and 0<=y+dc<C and src[x+dr][y+dc]==target)
   if not adj:continue
   seed=min(adj,key=lambda p:(p[0]-center[0])**2+(p[1]-center[1])**2)
   if ds[v][seed[0]][seed[1]]>0:ds[v][seed[0]][seed[1]]=0;q.append(seed)
  while q:
   x,y=q.popleft()
   for dr,dc in dirs:
    a,b=x+dr,y+dc
    if 0<=a<R and 0<=b<C and src[a][b]==target and ds[v][a][b]>ds[v][x][y]+1:ds[v][a][b]=ds[v][x][y]+1;q.append((a,b))
 out=[row[:] for row in src]
 for r in range(R):
  for c in range(C):
   if src[r][c]==target:
    ll=sorted((ds[v][r][c],v) for v in vals)
    if ll and (len(ll)==1 or ll[0][0]<ll[1][0]):out[r][c]=ll[0][1]
 return out
